/**
 * Geist Medium and Geist Mono Regular, subset to the characters a share image
 * uses, for the stateless social image (`app/(public)/s/[token]/image`).
 *
 * The image renderer needs font bytes at request time, and a Worker cannot
 * read the package's font files, so the subsets travel with the code (about
 * 50 KB together). Geist is licensed under the SIL Open Font License 1.1 (see
 * THIRD_PARTY_NOTICES.md), which permits subsetting and redistribution.
 *
 * Regenerate with fonttools:
 *   pyftsubset node_modules/geist/dist/fonts/geist-sans/Geist-Medium.ttf \
 *     --text="<printable ASCII plus × · – — → ’ ‘ “ ” …>" --layout-features=kern,tnum,lnum
 *   pyftsubset node_modules/geist/dist/fonts/geist-mono/GeistMono-Regular.ttf --text="…"
 * then base64 each output into the constants below.
 */

function bytes(base64: string): ArrayBuffer {
  const binary = atob(base64);
  const out = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) out[index] = binary.charCodeAt(index);
  return out.buffer;
}

const GEIST_MEDIUM =
  "";
const GEIST_MONO =
  "";

export function shareImageFonts(): {
  name: string;
  data: ArrayBuffer;
  weight: 400 | 500;
  style: "normal";
}[] {
  return [
    { name: "Geist", data: bytes(GEIST_MEDIUM), weight: 500, style: "normal" },
    { name: "Geist Mono", data: bytes(GEIST_MONO), weight: 400, style: "normal" },
  ];
}
